const links = Array.from(document.querySelectorAll('a, button')).filter(e => /18 or older/i.test(e.textContent || ''));
return JSON.stringify(links.map(e => {
  const r = e.getBoundingClientRect();
  return {tag: e.tagName, text: (e.textContent||'').trim().slice(0,60), x: Math.round(r.x+r.width/2), y: Math.round(r.y+r.height/2)};
}));

const v = SugarCube.State.variables;
// What stage-related vars exist?
return JSON.stringify({
  has_player: typeof v.player,
  has_npcs: typeof v.npcs,
  has_flags: typeof v.flags,
  player_keys: v.player ? Object.keys(v.player).slice(0,30) : null,
  npcs_keys: v.npcs ? Object.keys(v.npcs).slice(0,10) : null,
  npc_frank_stage: v.player ? v.player.npc_frank_stage : null,
}, null, 2);

const v = SugarCube.State.variables;
return JSON.stringify({
  core_traits: v.player.core_traits,
  flags: v.flags,
  npc_sample: v.npcs[Object.keys(v.npcs)[0]],
  location: v.player.current_location,
  time: v.game_state ? v.game_state.time_state : null,
}, null, 2);

const passages = Story.passages || {};
const names = Object.keys(passages).filter(n => /Location_.*[Bb]edroom|Frank.*edroom/i.test(n)).slice(0,15);
return JSON.stringify(names);

// SugarCube exposes passages via Story.passages but iteration differs by version
if (typeof Story === 'undefined') return 'no Story';
if (!Story.passages) {
  return 'Story exists, passages missing';
}
// Try iteration
const out = [];
for (const k in Story.passages) {
  if (/Location|edroom/i.test(k)) out.push(k);
  if (out.length >= 20) break;
}
return JSON.stringify(out);

if (typeof SugarCube === 'undefined') return 'no SugarCube';
// SugarCube exposes via SugarCube.Story
const sStory = SugarCube.Story;
if (!sStory) return 'no SugarCube.Story';
// get() takes title; lookup() iterates. Or .lookup is on a different namespace?
const allTitles = SugarCube.Story.passages ? Object.keys(SugarCube.Story.passages).slice(0,5) : 'no passages';
return JSON.stringify({allTitles_sample: allTitles, has_lookup: typeof SugarCube.Story.lookup, has_getAllInit: typeof SugarCube.Story.passages});

const all = Object.keys(SugarCube.Story.passages);
const filtered = all.filter(n => /Location_|edroom|Hallway/i.test(n));
return JSON.stringify(filtered.slice(0,20));

const v = SugarCube.State.variables;
// Set Maya to Stage 4 with bedroom invited + first night done
v.player.core_traits.npc_frank_stage = 4;
v.flags.frank_invited_to_bedroom = true;
v.flags.frank_bedroom_first_done = true;
v.flags.talked_to_frank_today = false;
v.flags.in_loop_mode = false;
v.flags.ready_for_climax = false;
// Set time to Tuesday 21:30 (weekday evening, schedule window 21:00-23:00)
v.game_state.time_state.current_day = 'Tuesday';
v.game_state.time_state.current_hour = 21;
v.game_state.time_state.current_minute = 30;
v.game_state.time_state.day = 2;
// Frank arousal already 0, so calm setter wins
return JSON.stringify({
  stage: v.player.core_traits.npc_frank_stage,
  invited: v.flags.frank_invited_to_bedroom,
  first_done: v.flags.frank_bedroom_first_done,
  time: v.game_state.time_state,
});
